package replay

import (
	"context"
	"errors"
	"fmt"
	"net/http"
	"sort"
	"strings"
	"sync"
	"time"

	"incident-replay/backend/internal/scenario"
	"incident-replay/backend/internal/store"

	"github.com/prometheus/client_golang/prometheus"
	"os"
	"strconv"
)

// ReplayState represents the current state of a replay run
//go:generate stringer -type=ReplayState

type ReplayState string

const (
	StateRunning ReplayState = "running"
	StateStopped ReplayState = "stopped"
	StateFailed  ReplayState = "failed"
)

// Stats holds statistics data for a replay run
// p95ms is the 95th percentile latency in milliseconds
// We store latencies in a slice to compute p95

type Stats struct {
	Requests       int64   `json:"requests"`
	Errors         int64   `json:"errors"`
	LatencySamples []int64 // latency samples in ms
	p95ms          int64
	mu             sync.Mutex
	latencyCap     int
	pos            int
}

// NewStatsWithCap creates a Stats with cap on latencySamples
func NewStatsWithCap(cap int) *Stats {
	return &Stats{
		LatencySamples: make([]int64, cap),
		latencyCap:     cap,
		pos:            0,
	}
}

// AddSample adds a latency sample (in milliseconds) and updates counters.
func (s *Stats) AddSample(latencyMs int64, isError bool) {
	s.mu.Lock()
	defer s.mu.Unlock()

	s.Requests++
	if isError {
		s.Errors++
	}
	// Only store samples of successful requests for latency calc
	if !isError {
		if s.latencyCap <= 0 {
			// no cap, append
			s.LatencySamples = append(s.LatencySamples, latencyMs)
		} else {
			// Ring buffer logic: overwrite oldest sample
			s.LatencySamples[s.pos] = latencyMs
			s.pos = (s.pos + 1) % s.latencyCap
		}
	}
}

// CalculateP95 calculates the 95th percentile latency from stored samples
func (s *Stats) CalculateP95() {
	s.mu.Lock()
	defer s.mu.Unlock()

	samples := []int64{}
	if s.latencyCap <= 0 {
		samples = s.LatencySamples
	} else {
		// Store samples may be partially filled if Requests < cap
		count := int(s.Requests - s.Errors)
		if count > s.latencyCap {
			count = s.latencyCap
		}
		samples = make([]int64, count)
		endPos := s.pos
		startPos := (endPos - count + s.latencyCap) % s.latencyCap

		if startPos < endPos {
			copy(samples, s.LatencySamples[startPos:endPos])
		} else if startPos > endPos {
			copy(samples, s.LatencySamples[startPos:])
			copy(samples[s.latencyCap-startPos:], s.LatencySamples[:endPos])
		}
	}

	if len(samples) == 0 {
		s.p95ms = 0
		return
	}

	// Copy and sort to find p95
	samplesCopy := make([]int64, len(samples))
	copy(samplesCopy, samples)
	sort.Slice(samplesCopy, func(i, j int) bool {
		return samplesCopy[i] < samplesCopy[j]
	})

	idx := int(float64(len(samplesCopy)) * 0.95)
	if idx > 0 {
		idx--
	}
	if idx < 0 {
		idx = 0
	}
	if idx >= len(samplesCopy) {
		idx = len(samplesCopy) - 1
	}
	s.p95ms = samplesCopy[idx]
}

// P95 returns the last computed p95 latency
func (s *Stats) P95() int64 {
	s.mu.Lock()
	defer s.mu.Unlock()
	return s.p95ms
}

// Run represents a single replay execution
// Stores state, start time, and stats

type Run struct {
	RunID     string
	State     ReplayState
	StartedAt time.Time
	Stats     *Stats
	mu        sync.Mutex
	// control
	cancel context.CancelFunc

	store      *store.RunStore
	report     store.Report
	finishedAt *time.Time
	// semaphore.Release called when run stops
	releaseSlot func()
}

const DefaultLatencySamplesCap = 10000

func NewRun(runID string, runStore *store.RunStore) *Run {
	cap := DefaultLatencySamplesCap
	if envVal := os.Getenv("LATENCY_SAMPLES_CAP"); envVal != "" {
		if v, err := strconv.Atoi(envVal); err == nil && v > 0 {
			cap = v
		}
	}
	return &Run{
		RunID:     runID,
		State:     StateRunning,
		StartedAt: time.Now().UTC(),
		Stats:     NewStatsWithCap(cap),
		store:     runStore,
		report:    make(store.Report),
	}
}

// persist saves the current report state to store
func (r *Run) persist() {
	if r.store == nil {
		return
	}
	_ = r.store.Save(r.RunID, r.report)
}

// MarkStopped marks the run as stopped
func (r *Run) MarkStopped() {
	gauge := promReplayRunsActive

	r.mu.Lock()
	defer r.mu.Unlock()
	if r.State == StateRunning {
		r.State = StateStopped
		if r.cancel != nil {
			r.cancel()
		}
		now := time.Now().UTC()
		r.finishedAt = &now

		// update report
		r.report["state"] = r.State
		r.report["finishedAt"] = r.finishedAt.Format(time.RFC3339)
		r.persist()

		gauge.Dec()

		if r.releaseSlot != nil {
			r.releaseSlot()
		}
	}
}

// MarkFailed marks the run as failed
func (r *Run) MarkFailed() {
	r.mu.Lock()
	defer r.mu.Unlock()
	r.State = StateFailed
	if r.cancel != nil {
		r.cancel()
	}
	now := time.Now().UTC()
	r.finishedAt = &now

	// update report
	r.report["state"] = r.State
	r.report["finishedAt"] = r.finishedAt.Format(time.RFC3339)
	r.persist()

	promReplayRunsActive.Dec()

	if r.releaseSlot != nil {
		r.releaseSlot()
	}
}

// AddSample adds a latency sample and error flag to stats
func (r *Run) AddSample(latencyMs int64, isError bool) {
	r.Stats.AddSample(latencyMs, isError)

	// Update report fields for stats
	r.mu.Lock()
	defer r.mu.Unlock()

	r.report["stats"] = map[string]interface{}{
		"requests": r.Stats.Requests,
		"errors":   r.Stats.Errors,
		"p95ms":    r.Stats.P95(),
	}
	r.persist()
}

// UpdateP95 recalculates the p95 for the run stats
func (r *Run) UpdateP95() {
	r.Stats.CalculateP95()

	// update report
	r.mu.Lock()
	defer r.mu.Unlock()

	r.report["stats"] = map[string]interface{}{
		"requests": r.Stats.Requests,
		"errors":   r.Stats.Errors,
		"p95ms":    r.Stats.P95(),
	}
	r.persist()
}

// StatusResponse returns the JSON-compatible status response
func (r *Run) StatusResponse() map[string]interface{} {
	resp := map[string]interface{}{
		"runId":     r.RunID,
		"state":     r.State,
		"startedAt": r.StartedAt.Format(time.RFC3339),
		"stats": map[string]interface{}{
			"requests": r.Stats.Requests,
			"errors":   r.Stats.Errors,
			"p95ms":    r.Stats.P95(),
		},
	}
	if r.finishedAt != nil {
		resp["finishedAt"] = r.finishedAt.Format(time.RFC3339)
	}
	return resp
}

// Runner manages active replay runs
// Stores runs in memory mapped by runID

type Runner struct {
	runs       map[string]*Run
	mu         sync.Mutex
	httpClient *http.Client
	runStore   *store.RunStore

	// semaphore for concurrency limit
	concurrencySem chan struct{}

	maxConcurrentRuns int
}

// Prometheus metrics for replay
var (
	promReplayRequestsTotal = prometheus.NewCounter(
		prometheus.CounterOpts{
			Name: "replay_requests_total",
			Help: "Total number of replay requests started.",
		},
	)
	promReplayErrorsTotal = prometheus.NewCounter(
		prometheus.CounterOpts{
			Name: "replay_errors_total",
			Help: "Total number of errors occurred during replay.",
		},
	)
	promReplayRunsActive = prometheus.NewGauge(
		prometheus.GaugeOpts{
			Name: "replay_runs_active",
			Help: "Current number of active replay runs.",
		},
	)
	promReplayRequestDurationMs = prometheus.NewHistogram(
		prometheus.HistogramOpts{
			Name:    "replay_request_duration_ms",
			Help:    "Histogram of replay request durations in milliseconds.",
			Buckets: prometheus.ExponentialBuckets(1, 2, 10),
		},
	)
)

func init() {
	prometheus.MustRegister(promReplayRequestsTotal)
	prometheus.MustRegister(promReplayErrorsTotal)
	prometheus.MustRegister(promReplayRunsActive)
	prometheus.MustRegister(promReplayRequestDurationMs)
}

type StartParams struct {
	ScenarioID    string
	TargetBaseURL string
	RPS           int
	Duration      time.Duration

	// New optional fields
	Mode        string  // burst|timestamp
	Speed       float64 // >0
	MaxDelayMs  int64   // >=0
	StartFromTs string  // RFC3339 timestamp
	EndAtTs     string  // RFC3339 timestamp
}

type StatusStats struct {
	Requests int64 `json:"requests"`
	Errors   int64 `json:"errors"`
	P95ms    int64 `json:"p95ms"`
}

type Status struct {
	RunID     string      `json:"runId"`
	State     ReplayState `json:"state"`
	StartedAt string      `json:"startedAt"`
	Stats     StatusStats `json:"stats"`
}

var ErrTooManyConcurrentRuns = errors.New("too many concurrent runs")

func NewRunner() *Runner {
	maxConc := 3
	if env := os.Getenv("MAX_CONCURRENT_RUNS"); env != "" {
		if v, err := strconv.Atoi(env); err == nil && v > 0 {
			maxConc = v
		}
	}

	return &Runner{
		runs:              make(map[string]*Run),
		httpClient:        &http.Client{Timeout: 10 * time.Second},
		runStore:          store.NewRunStore(),
		concurrencySem:    make(chan struct{}, maxConc),
		maxConcurrentRuns: maxConc,
	}
}

func parseTimestamp(s string) (time.Time, error) {
	if strings.TrimSpace(s) == "" {
		return time.Time{}, nil
	}
	return time.Parse(time.RFC3339, s)
}

func (r *Runner) Start(params StartParams) (string, error) {
	if strings.TrimSpace(params.TargetBaseURL) == "" {
		return "", errors.New("targetBaseUrl is required")
	}
	if params.RPS <= 0 {
		return "", errors.New("rps must be > 0")
	}
	if params.Duration <= 0 {
		return "", errors.New("duration must be > 0")
	}
	if strings.TrimSpace(params.ScenarioID) == "" {
		return "", errors.New("scenarioId is required")
	}

	if params.Mode == "" {
		params.Mode = "burst"
	}

	// Validate mode
	if params.Mode != "burst" && params.Mode != "timestamp" {
		return "", errors.New("mode must be 'burst' or 'timestamp'")
	}

	if params.Speed != 0 && params.Speed <= 0 {
		return "", errors.New("speed must be > 0")
	}

	if params.MaxDelayMs < 0 {
		return "", errors.New("maxDelayMs must be >= 0")
	}

	// Validate timestamps format StartFromTs, EndAtTs if not empty
	startFrom, err := parseTimestamp(params.StartFromTs)
	if err != nil {
		return "", fmt.Errorf("invalid startFromTs: %w", err)
	}
	endAt, err := parseTimestamp(params.EndAtTs)
	if err != nil {
		return "", fmt.Errorf("invalid endAtTs: %w", err)
	}

	if !startFrom.IsZero() && !endAt.IsZero() && !(startFrom.Before(endAt) || startFrom.Equal(endAt)) {
		return "", errors.New("startFromTs must be before endAtTs")
	}

	// Load scenario events
	rawEvents, err := scenario.LoadScenario(params.ScenarioID)
	if err != nil {
		return "", fmt.Errorf("load scenario error: %w", err)
	}

	// In timestamp mode, we require events to have valid ts and sort them
	var events []scenario.Event
	if params.Mode == "timestamp" {
		return "", errors.New("timestamp mode is not implemented yet")
	} else {
		// For burst mode, use raw events
		events = rawEvents
	}

	runID := fmt.Sprintf("run-%d", time.Now().UTC().UnixNano())

	// acquire semaphore slot
	select {
	case r.concurrencySem <- struct{}{}:
		// acquired
	default:
		return "", ErrTooManyConcurrentRuns
	}

	// update prometheus counter for requests
	promReplayRequestsTotal.Inc()

	// Create run and start the goroutine
	run := NewRun(runID, r.runStore)
	ctx, cancel := context.WithCancel(context.Background())
	run.cancel = cancel

	// set releaseSlot callback to release semaphore
	run.releaseSlot = func() {
		<-r.concurrencySem
	}

	r.mu.Lock()
	r.runs[runID] = run
	r.mu.Unlock()

	// Initial report state
	run.mu.Lock()
	run.report["runId"] = runID
	run.report["state"] = StateRunning
	run.report["startedAt"] = run.StartedAt.Format(time.RFC3339)
	run.persist()
	run.mu.Unlock()

	promReplayRunsActive.Inc()

	// Start replay in goroutine
	go r.runReplay(ctx, run, events, params)

	return runID, nil
}

func (r *Runner) runReplay(ctx context.Context, run *Run, events []scenario.Event, params StartParams) {
	// We want to generate up to params.RPS requests per second for params.Duration
	// In burst mode, we just send events in a burst for simplicity.

	startTime := time.Now()
	endTime := startTime.Add(params.Duration)

	ticker := time.NewTicker(time.Second / time.Duration(params.RPS))
	defer ticker.Stop()

	i := 0
	eventsCount := len(events)

	for {
		select {
		case <-ctx.Done():
			run.MarkStopped()
			return
		case now := <-ticker.C:
			if now.After(endTime) {
				run.MarkStopped()
				return
			}

			if i >= eventsCount {
				run.MarkStopped()
				return
			}

			event := events[i]
			i++

			start := time.Now()
			// Build HTTP request
			rq, err := http.NewRequest(event.Method, strings.TrimRight(params.TargetBaseURL, "/")+event.Path, strings.NewReader(event.Body))
			if err != nil {
				run.AddSample(0, true)
				promReplayErrorsTotal.Inc()
				continue
			}

			// Set headers
			for k, v := range event.Headers {
				rq.Header.Set(k, v)
			}

			resp, err := r.httpClient.Do(rq)
			latencyMS := time.Since(start).Milliseconds()
			if err != nil {
				run.AddSample(latencyMS, true)
				promReplayErrorsTotal.Inc()
				continue
			}
			resp.Body.Close()
			if resp.StatusCode >= 400 {
				run.AddSample(latencyMS, true)
				promReplayErrorsTotal.Inc()
			} else {
				run.AddSample(latencyMS, false)
			}
		}
	}
}

func (r *Runner) Stop(runID string) error {
	r.mu.Lock()
	run, ok := r.runs[runID]
	r.mu.Unlock()
	if !ok {
		return fmt.Errorf("runId not found")
	}

	run.MarkStopped()
	return nil
}

func (r *Runner) Status(runID string) (Status, error) {
	r.mu.Lock()
	run, ok := r.runs[runID]
	r.mu.Unlock()
	if !ok {
		return Status{}, fmt.Errorf("runId not found")
	}

	return Status{
		RunID:     runID,
		State:     run.State,
		StartedAt: run.StartedAt.Format(time.RFC3339),
		Stats: StatusStats{
			Requests: run.Stats.Requests,
			Errors:   run.Stats.Errors,
			P95ms:    run.Stats.P95(),
		},
	}, nil
}

func (r *Runner) ListRuns(limit int) ([]map[string]interface{}, error) {
	r.runStore.mu.Lock()
	// To list all runIDs
	runIDs, err := r.runStore.List(limit)
	r.runStore.mu.Unlock()
	if err != nil {
		return nil, err
	}

	var reports []map[string]interface{}
	for _, runID := range runIDs {
		rep, err := r.runStore.Load(runID)
		if err != nil {
			// ignore error and continue
			continue
		}
		reports = append(reports, rep)
	}

	return reports, nil
}

func (r *Runner) LoadReport(runID string) (store.Report, error) {
	return r.runStore.Load(runID)
}

package replay

import (
	"testing"

	"github.com/stretchr/testify/assert"
)

func TestValidateRPS(t *testing.T) {
	// This is a placeholder for actual validation tests.
	// Ensure that validation code importing fmt was removed from production test files.
	assert.True(t, true)
}

func TestLatencySamplesCap(t *testing.T) {
	cap := 5
	stats := NewStatsWithCap(cap)

	// Add more than cap samples
	for i := 1; i <= 10; i++ {
		stats.AddSample(int64(i*10), false)
	}

	stats.CalculateP95()

	// Since we keep only last 'cap' samples, samples are 60,70,80,90,100
	// sorted: 60,70,80,90,100
	// p95 index: floor(0.95*5)-1 = 4-1=3
	// value = 90
	p95 := stats.P95()
	if p95 != 90 {
		t.Errorf("expected p95 90, got %d", p95)
	}
}

func TestRunAddSampleWithCap(t *testing.T) {
	cap := 3
	// override env temporarily
	old := os.Getenv("LATENCY_SAMPLES_CAP")
	defer os.Setenv("LATENCY_SAMPLES_CAP", old)
	os.Setenv("LATENCY_SAMPLES_CAP", "3")

	run := NewRun("test-run", nil)

	// Add 5 samples
	run.AddSample(10, false)  // should store 10
	run.AddSample(20, false)  // should store 20
	run.AddSample(30, false)  // should store 30
	run.AddSample(40, false)  // overwrite pos=0 with 40
	run.AddSample(50, false)  // overwrite pos=1 with 50

	// Calculate p95
	run.UpdateP95()

	p95 := run.Stats.P95()

	// samples in buffer are [40,50,30], sorted [30,40,50]. p95 index floor(0.95*3)-1=1-1=0->30
	if p95 != 30 {
		t.Errorf("expected p95 30, got %d", p95)
	}

	// Check requests count matches
	if run.Stats.Requests != 5 {
		t.Errorf("expected requests 5, got %d", run.Stats.Requests)
	}
}
